def service(row):
 slug, name, _, _, price, formats, deliver, scope, faq = row
 c = CONTENT[slug]
 image = f'assets/service-{slug}-v1.webp'
 body = f'''<div class="service29 service29-{slug}"><section class="service29-intro"><div class="wrap"><nav class="breadcrumb" aria-label="Хлебные крошки"><a href="index.html">Главная</a><span aria-hidden="true">/</span><a href="services.html">Услуги</a><span aria-hidden="true">/</span><span aria-current="page">{name}</span></nav><div class="service29-hero"><div><h1>{c['title']}</h1><p>{c['intro']}</p><div class="website-hero-actions"><a class="btn primary" href="contacts.html?service={slug}">{c['cta']}</a><a class="website-secondary" href="#service-scenario">Как это работает</a></div><p class="service29-price">{price}</p></div><figure class="service29-art"><img src="{image}" width="960" height="640" fetchpriority="high" decoding="async" alt="{c['alt']}"><figcaption>Иллюстрация сценария</figcaption></figure></div></div></section>'''
 body += f'<section class="wrap service29-scenario" id="service-scenario"><div class="service29-heading"><h2>{c["heading"]}</h2><p>{c["explanation"]}</p></div><ol class="service29-route" aria-label="Этапы сценария">'
 for label, title, text in c['nodes']:
  body += f'<li data-app-reveal><span class="service29-route-label">{label}</span><h3>{title}</h3><p>{text}</p></li>'
 body += f'</ol><p class="service29-caption">{c["note"]}</p></section>'
 body += f'<section class="service29-directions"><div class="wrap"><h2>{c["formats_title"]}</h2><div class="service29-formats">'+''.join(f'<article data-app-reveal><h3>{escape(title)}</h3><p>{escape(text)}</p></article>' for title,text in formats)+'</div></div></section>'
 body += '<section class="wrap service29-delivery"><div><h2>Что передаём<br>вместе с решением</h2><p>Состав работ и критерии приёмки фиксируем после знакомства с вашим процессом.</p></div><ol>'+''.join(f'<li>{escape(x)}</li>' for x in deliver)+'</ol></section>'
 body += f'<section class="wrap service29-budget"><h2>Границы проекта и стоимость</h2><strong>{price}</strong><p>{escape(scope)}</p></section>'
 case = 'pilotspace' if slug == 'integrations' else 'mu56'
 case_name = 'PilotSpace' if case == 'pilotspace' else 'Мир улыбок'
 body += f'<section class="wrap service29-proof"><div><h2>Реальный проект</h2><p>{case_name}: посмотрите страницы и описание проекта в портфолио.</p><a class="website-secondary" href="case-{case}.html">Посмотреть проект</a></div><a href="case-{case}.html" aria-label="Посмотреть проект {case_name}"><img src="assets/{case}-home-desktop.jpg" width="1265" height="712" loading="lazy" decoding="async" alt="Главная страница проекта {case_name}"></a></section>'
 body += '<section class="wrap website-faq"><h2>Перед началом работы</h2><div>'+''.join(f'<details><summary>{escape(q)}<span aria-hidden="true">+</span></summary><p>{escape(a)}</p></details>' for q,a in faq)+'</div></section>'
 return body + stage25_enquiry.enquiry().replace('href="contacts.html"', f'href="contacts.html?service={slug}"') + '</div>'
